"""Loading into the website's table, against a real, throwaway Postgres server.

Skipped when the Postgres server programs are not installed (they are in the
pixi test environment) or when running as root, which Postgres refuses.
"""

import os
import shutil
import socket
import subprocess
import time

import pandas as pd
import psycopg
import pytest

from gaplist import deploy, export

# The website's table, as its Entity Framework model defines it, in Postgres terms.
TABLE_SQL = """
CREATE TABLE "Targetlist" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Kingdom" text, "Phylum" text, "Class" text, "Order" text, "Family" text, "Genus" text, "Species" text,
    "OwnBarcodes" integer NOT NULL, "OtherBarcodes" integer NOT NULL,
    "Collected" integer NOT NULL, "Wanted" integer NOT NULL,
    "SpeciesWithBarcode" integer GENERATED ALWAYS AS
        (CASE WHEN ("OwnBarcodes" + "OtherBarcodes") > 0 THEN 1 ELSE 0 END) STORED,
    "AllBarcodes" integer GENERATED ALWAYS AS ("OwnBarcodes" + "OtherBarcodes") STORED,
    "SpeciesLocality" text, "SpeciesOccurrenceStatus" text,
    "DateCreated" timestamp NOT NULL, "DateModified" timestamp NOT NULL
)
"""

needs_postgres = pytest.mark.skipif(
    shutil.which("initdb") is None or os.geteuid() == 0, reason="needs Postgres server programs, not as root"
)


@pytest.fixture(scope="module")
def server(tmp_path_factory):
    base = tmp_path_factory.mktemp("pg")
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        port = s.getsockname()[1]
    subprocess.run(["initdb", "-D", str(base / "data"), "-U", "test", "--auth=trust"], check=True,
                   capture_output=True)
    subprocess.run(["pg_ctl", "-D", str(base / "data"), "-o", f"-p {port} -k {base} -h 127.0.0.1",
                    "-l", str(base / "log"), "start"], check=True, capture_output=True)
    for _ in range(50):
        try:
            psycopg.connect(host="127.0.0.1", port=port, user="test", dbname="postgres").close()
            break
        except psycopg.OperationalError:
            time.sleep(0.2)
    yield {"host": "127.0.0.1", "port": str(port), "user": "test", "dbname": "postgres", "password": "x"}
    subprocess.run(["pg_ctl", "-D", str(base / "data"), "stop", "-m", "fast"], capture_output=True)


@pytest.fixture
def seed_file(tmp_path):
    rows = [
        ["Animalia", "Arthropoda", "Insecta", "Diptera", "Chironomidae", "Aagaardia", "Aagaardia protensa",
         "GBIF;BOLD", "", 0, 1, 1, 2],
        ["Animalia", "Arthropoda", "Insecta", "Diptera", "", "Orphanus", "Orphanus solus", "LF", "gap", 0, 1, 0, 0],
    ]
    path = tmp_path / "targetlist_seed.tsv"
    pd.DataFrame(rows, columns=export.SEED_COLUMNS).to_csv(path, sep="\t", index=False)
    return path


@needs_postgres
def test_dry_run_changes_nothing_then_confirm_replaces(server, seed_file):
    with psycopg.connect(**server) as con:
        con.execute('DROP TABLE IF EXISTS "Targetlist"')
        con.execute(TABLE_SQL)
        con.execute("""INSERT INTO "Targetlist" ("Species", "OwnBarcodes", "OtherBarcodes", "Collected", "Wanted",
                       "DateCreated", "DateModified") VALUES ('Old species', 0, 0, 0, 1, now(), now())""")
    dry = deploy.deploy(seed_file=seed_file, connection=server)
    assert dry.ok and "lists 1 species" in dry.message and "Nothing was changed" in dry.message
    done = deploy.deploy(confirm=True, seed_file=seed_file, connection=server)
    assert done.ok, done.message
    with psycopg.connect(**server) as con:
        rows = con.execute(
            'SELECT "Species", "Family", "SpeciesOccurrenceStatus", "AllBarcodes", "SpeciesWithBarcode" '
            'FROM "Targetlist" ORDER BY "Species"').fetchall()
    assert rows == [("Aagaardia protensa", "Chironomidae", "", 3, 1), ("Orphanus solus", "", "gap", 0, 0)]


@needs_postgres
def test_refuses_unexpected_table(server, seed_file):
    with psycopg.connect(**server) as con:
        con.execute('DROP TABLE IF EXISTS "Targetlist"')
        con.execute('CREATE TABLE "Targetlist" ("Id" integer, "Species" text)')
    result = deploy.deploy(confirm=True, seed_file=seed_file, connection=server)
    assert not result.ok and "lacks the column(s)" in result.message


def test_missing_settings_are_explained(tmp_path, seed_file, monkeypatch):
    monkeypatch.setattr(deploy.paths, "repo_root", lambda: tmp_path)
    for name in ("TARGETLIST_DB_HOST", "TARGETLIST_DB_NAME", "TARGETLIST_DB_USER", "TARGETLIST_DB_PASSWORD"):
        monkeypatch.delenv(name, raising=False)
    result = deploy.deploy(seed_file=seed_file)
    assert not result.ok and "fill in TARGETLIST_DB_HOST" in result.message
